#!/usr/bin/env bash
# Regenerates scripts/proto-app.mjs: verbatim method bodies from Workbench v10.dc.html wrapped
# in a class, so the geometry / analysis / lane code can run in Node for golden files.
set -euo pipefail
cd "$(dirname "$0")/.."
WB="Form submission process/Workbench v10.dc.html"
OUT=scripts/proto-app.mjs
{
cat <<'HDR'
// GENERATED by scripts/extract-proto.sh — verbatim method bodies from Workbench v10.dc.html
// (line ranges in the header of each block). Wrapped in a class with the prototype's fields so
// the pure geometry / analysis / lane code can run in Node for golden files. Do not edit by hand.
/* eslint-disable */
import * as P from '../Form submission process/presets.js';
import * as S from '../Form submission process/sim-engine.js';
import * as PD from '../Form submission process/paradigms.js';
import * as SP from '../Form submission process/sim-paradigms.js';
import * as A from '../Form submission process/analyze-paradigms.js';
import * as L from '../Form submission process/layout.js';
import * as X from '../Form submission process/examples.js';

export class ProtoApp {
  constructor(paradigm, nodes, edges, regions, opts = {}) {
    this.P = P; this.S = S; this.PD = PD; this.SP = SP; this.A = A; this.L = L; this.X = X;
    this.props = { router: 'channels', channelGap: 'normal', zoomSnap: 'free', ...(opts.props || {}) };
    this.state = { paradigm, nodes, edges, regions, rps: opts.rps ?? 1000, mode: opts.mode ?? 'simulate', ui: { labels: true, tidy: true, semantic: true, ...(opts.ui || {}) } };
    this.nodeH = opts.nodeH || {}; this.nodeHMax = {}; this.metrics = opts.metrics || null; this.drag = null; this.nhist = {};
    this._nById = {}; nodes.forEach(n => this._nById[n.id] = n);
    this.cEl = null; this.docs = {}; this.hist = []; this.future = []; this.touched = false;
  }
  get T() { return this.PD.PARADIGMS[this.state.paradigm]; }
  paraId() { return this.state.paradigm; }
  setState(p) { Object.assign(this.state, p); this._nById = {}; this.state.nodes.forEach(n => this._nById[n.id] = n); }
  GK = { compute: 'service', net: 'tool', data: 'database', msg: 'queue', rel: 'agent' };
HDR
for range in 715-725 734-757 783-828 835-836 883-883 905-925 935-1131 1137-1160 1530-1530 1615-1625 1649-1810 1861-1866 1895-1930; do
  a=${range%-*}; b=${range#*-}; echo "  // ---- WB ${a}–${b} ----"; sed -n "${a},${b}p" "$WB"; done
echo "}"
} > "$OUT"
echo "wrote $OUT"
